\label{rem:second-moment-algorithm-locality}
We note that the warm start in \cref{alg:annealed-glauber-ergodic-second-moments} is computed via an ergodic statistic of the underlying local Markov chain itself. This differs from the prior warm-started local algorithms of~\citep{richard2014statistical,anandkumar2017homotopy,lovig2025almost}, which obtain their initializations from the observed tensor $Y$ via a global algorithm. Furthermore, because this ergodic statistic is accumulated online, the eigenvector computation of Step~3 in \cref{alg:annealed-glauber-ergodic-second-moments} can itself be carried out locally, by evolving Oja's flow~\citep{oja1982simplified,kumar2023streaming} alongside the high temperature trajectory,
\begin{align*}
    \dot z_t=\eta_t\left\langle F(\widetilde{X}_t), z_t \right\rangle F(\widetilde{X}_t),
    \qquad
    F(x)=(x,1)\in\mathbb{R}^{N+1},
    \qquad
    z_0\sim\operatorname{Uniform}(\mathbb{S}^N),
\end{align*}
with step sizes $\eta_t>0$, and replacing $(v,a)$ with $z_{T_{\mathrm{av}}}$ normalized to unit norm and oriented so that its last coordinate is nonnegative. Since the trajectory of continuous-time Glauber dynamics is piecewise constant (see \cref{subsec:cts-glauber} and~\citep[Chapter~20]{levin2017markov}), this ODE can be solved in closed form between consecutive updates of the chain, and over each such interval it amounts to a rank-one update of $z_t$ determined by the current configuration. The resulting algorithm maintains only the current configuration and a single auxiliary vector, much like the running average in \cref{alg:averaged-annealed-glauber}. For simplicity, we retain the explicit eigenvector computation, since analyzing this variant would divert attention from our main ideas.

\label{lem:discrete-product-rule}
For any $f,g:\Omega_N\to\mathbb{R}$, $i\in[N]$, and $x\in\Omega_N$,
\begin{align*}
    \partial_i(fg)(x)
    =f(x)\partial_i g(x)+g(x)\partial_i f(x)
    -2x_i\partial_i f(x)\partial_i g(x).
\end{align*}

\label{lem:hypercube-stein}
For any $f:\Omega_N\to\mathbb{R}$,
\begin{align*}
    \mathbb{E}_\pi[\nabla_\Omega f(x)]&=\mathbb{E}_\pi[xf(x)],\\
    \mathbb{E}_\pi[\nabla_\Omega^2 f(x)]
    &=\frac{1}{2}\mathbb{E}_\pi\left[x\nabla_\Omega f(x)^\top+\nabla_\Omega f(x)x^\top\right]
    =\mathbb{E}_\pi\left[(xx^\top-I)f(x)\right].
\end{align*}

Since $\pi$ is a product measure we obtain the following by conditioning on $x_{\neg i}$ for some $i \in [N]$
\begin{align*}
    \mathbb{E}_\pi[x_i f(x)]
    =\mathbb{E}_\pi\left[\nicefrac{1}{2}f(x_{\neg i},x_i=+1)
                  -\nicefrac{1}{2}f(x_{\neg i},x_i=-1)\right]
    =\mathbb{E}_\pi[\partial_i f(x)].
\end{align*}


which proves the first identity elementwise. Applying it to $\partial_j f$, we obtain $\mathbb{E}_\pi[\partial_i\partial_j f]=\mathbb{E}_\pi[x_i\partial_j f]$. Since discrete partial derivatives commute, we infer the following by exchanging $i$ and $j$ and averaging:
\begin{align*}
    \mathbb{E}_\pi[\partial_i\partial_j f(x)]
    =\frac{1}{2}\mathbb{E}_\pi[x_i\partial_j f(x)+x_j\partial_i f(x)].
\end{align*}
For distinct $i,j \in [N]$, we have $\partial_j(x_i f)=x_i\partial_j f$. Applying the first identity once more, we obtain
\begin{align*}
    \mathbb{E}_\pi[\partial_i\partial_j f(x)]
    =\mathbb{E}_\pi[\partial_j(x_i f)(x)]
    =\mathbb{E}_\pi[x_i x_j f(x)].
\end{align*}

For $i=j$, both $\partial_i^2 f$ and $(x_i^2-1)f$ vanish, and $\mathbb{E}_\pi[x_i\partial_i f]=0$ because $\partial_i f$ does not depend on $x_i$. Combining these identities entrywise proves the second identity.

\label{lem:rademacher-moments}
Let $N\geqslant2$, $x\sim\pi$, and $S_N=\sum_{i=1}^N x_i$. For every fixed integer $\ell\geqslant1$, we have
\begin{align*}
    \mathbb{E}_\pi[S_N^\ell]
    =\begin{cases}
        0, & \text{if $\ell$ is odd},\\
        (\ell-1)!!\,N^{\nicefrac{\ell}{2}}+O_\ell(N^{\nicefrac{\ell}{2}-1}), & \text{if $\ell$ is even}.
    \end{cases}
\end{align*}
Moreover, for any distinct $i,j\in[N]$,
\begin{align*}
    \mathbb{E}_\pi[x_ix_jS_N^\ell]
    =\begin{cases}
        0, & \text{if $\ell$ is odd},\\
        \ell(\ell-1)!!\,N^{\nicefrac{\ell}{2}-1}+O_\ell(N^{\nicefrac{\ell}{2}-2}), & \text{if $\ell$ is even}.
    \end{cases}
\end{align*}

Let $B_N\sim\operatorname{Bin}(N,\nicefrac{1}{2})$. Since $S_N\overset{\mathrm{d}}{=}2(B_N-\nicefrac{N}{2})$, the first claim follows from the standard centered moment formulas for binomial random variables \citep[Theorem~3]{skorski2025handy}. For the second claim, we first observe that $\mathbb{E}_\pi[x_ix_jS_N^\ell]=0$ for odd $\ell$ by symmetry. For even $\ell$, the identity
\begin{align*}
    S_N^2=N+2\sum_{i<j}x_ix_j
\end{align*}
and exchangeability imply the following
\begin{align*}
    \mathbb{E}_\pi[S_N^{\ell+2}]
    =N\mathbb{E}_\pi[S_N^\ell]+N(N-1)\mathbb{E}_\pi[x_ix_jS_N^\ell].
\end{align*}
Rearranging and applying the first claim, we obtain
\begin{align*}
    \mathbb{E}_\pi[x_ix_jS_N^\ell]
    &=\frac{\mathbb{E}_\pi[S_N^{\ell+2}]-N\mathbb{E}_\pi[S_N^\ell]}{N(N-1)}=\frac{1}{N(N-1)}\left[
        \bigl((\ell+1)!!-(\ell-1)!!\bigr)N^{\nicefrac{\ell}{2}+1}
        +O_\ell(N^{\nicefrac{\ell}{2}})
    \right]\\
    &=\ell(\ell-1)!!\,N^{\nicefrac{\ell}{2}-1}+O_\ell(N^{\nicefrac{\ell}{2}-2}).
\end{align*}

