\label{lem:single-site-change-measure}
Fix $T>0$, and let $\mathbb{Q}^T$ denote the law of single-site dynamics up to time $T$, with spin update kernel $q$ and trajectory $(X_t)_{0\leqslant t\leqslant T}$. Let $a_i(z,t)$ denote tilts that are predictable with respect to the filtration of single-site dynamics up to time $T$, satisfying $0<a_i(z,t)\leqslant C$ for a deterministic $C<\infty$ and all $i\in[N]$, $z\in\{\pm1\}$, and $t\leqslant T$. For $0\leqslant t\leqslant T$, define
\begin{align*}
    L_t^a
    =\exp\left(\sum_{n:T_n\leqslant t}\log a_{I_n}(Z_n,T_n)
    -\int_0^t\sum_{i=1}^N\sum_{z\in\{\pm1\}}
    q(z\mid i,s,X_{s^-})\bigl(a_i(z,s)-1\bigr)\,ds\right).
\end{align*}
Then $(L_t^a)_{0\leqslant t\leqslant T}$ is a mean-one martingale under $\mathbb{Q}^T$. Define the tilted law $\mathbb{Q}^{T,a}$ by $\frac{d\mathbb{Q}^{T,a}}{d\mathbb{Q}^T}=L_T^a$. Under $\mathbb{Q}^{T,a}$, updates with mark $(i,z)$ have intensity $a_i(z,t)q(z\mid i,t,X_{t^-})$ for $t\leqslant T$, and $X_0$ has the same distribution as under $\mathbb{Q}^T$.

\label{avg-discrete-grad-snr}
Let $H$ denote the tensor PCA Hamiltonian defined in \cref{eq:tensor-pca-hamiltonian}, and define the average gradient $u_H\doteq\mathbb{E}_\pi[\nabla_\Omega H(x)]$. Then, the following holds:
\begin{enumerate}
    \item If $k$ is even, then $u_H=0$ holds deterministically.
    \item If $k$ is odd, then $u_H=N\lambda\alpha_N\theta^{\star}+\zeta$, where $\zeta\doteq\mathbb{E}_\pi[xH_0(x)]\sim\mathcal{N}(0,\sigma_N^2I)$, $\alpha_N\asymp_k N^{-\nicefrac{k}{2}}$, and $\sigma_N^2=\alpha_N\sqrt{N}\asymp_k N^{-\tfrac{k-1}{2}}$.
\end{enumerate}

By Stein's Lemma (\cref{lem:hypercube-stein}) and \cref{eq:tensor-pca-hamiltonian},
\begin{align}
\label{eq:average-gradient-decomposition}
    u_H=\mathbb{E}_\pi[xH(x)]
    =N\lambda\mathbb{E}_\pi[xm(x)^k]+\mathbb{E}_\pi[xH_0(x)].
\end{align}
If $k$ is even, then $H(-x)=H(x)$, and invariance of $\pi$ under $x\mapsto-x$ implies that $u_H=0$.

Henceforth, assume $k$ is odd. We first analyze the signal term in \cref{eq:average-gradient-decomposition}. Let $D=\operatorname{diag}(x^{\star})$. Since $D \in O(N,\mathbb Z)$, for $x\sim\pi$, the vector $y=Dx$ is also distributed according to $\pi$. Define $\widetilde m(y)=N^{-1}\sum_{i=1}^N y_i$, the overlap with the all-ones vector. We observe that
\begin{align*}
    m(x)
    =\frac{1}{N}\sum_{i=1}^N x^{\star}_i x_i
    =\frac{1}{N}\sum_{i=1}^N(Dx)_i
    =\widetilde m(y).
\end{align*}
Moreover, $D^2=I$, so $x=Dy$. Consequently,
\begin{align}
\label{eq:average-gradient-signal-transform}
    \mathbb{E}_{x\sim\pi}[xm(x)^k]
    =\mathbb{E}_{y\sim\pi}[Dy\,\widetilde m(y)^k]
    =D\mathbb{E}_{y\sim\pi}[y\,\widetilde m(y)^k].
\end{align}

Now let $P$ be any permutation matrix. Since $Py\sim\pi$ whenever $y\sim\pi$, and $\widetilde m(Py)=\widetilde m(y)$, we have
\begin{align*}
    \mathbb{E}_{y\sim\pi}[y\,\widetilde m(y)^k]
    =\mathbb{E}_{y\sim\pi}[Py\,\widetilde m(Py)^k]
    =P\mathbb{E}_{y\sim\pi}[y\,\widetilde m(y)^k].
\end{align*}
Since $\mathbb{E}_{y\sim\pi}[y\,\widetilde m(y)^k]$ is fixed by every permutation matrix, it is of the form $c\mathbf{1}$ for some $c\in\mathbb{R}$. We conclude from \cref{eq:average-gradient-signal-transform} that
\begin{align*}
    \mathbb{E}_{x\sim\pi}[xm(x)^k]
    =cD\mathbf{1}
    =cx^{\star}
    =\alpha_N\theta^{\star},
\end{align*}
where $\alpha_N=c\sqrt N$. Taking the inner product with the unit vector $\theta^{\star}$, we compute $\alpha_N$ as follows:
\begin{align}
\label{eq:average-gradient-alpha-moment}
    \alpha_N
    &=\mathbb{E}_{x\sim\pi}[\left\langle x, \theta^{\star} \right\rangle m(x)^k]
    =\sqrt N\,\mathbb{E}_{x\sim\pi}[m(x)^{k+1}]\nonumber\\
    &=\sqrt N\,\mathbb{E}_{y\sim\pi}[\widetilde m(y)^{k+1}]
    =N^{-k-\nicefrac{1}{2}}\mathbb{E}_{y\sim\pi}\left[\left(\sum_{i=1}^N y_i\right)^{k+1}\right].
\end{align}
Since $k+1$ is even, we infer from \cref{lem:rademacher-moments} that
\begin{align*}
    \alpha_N
    =N^{-k-\nicefrac{1}{2}}\left[k!!\,N^{\tfrac{k+1}{2}}+O_k(N^{\tfrac{k-1}{2}})\right]
    \asymp_k N^{-\nicefrac{k}{2}}.
\end{align*}

We now analyze the noise term in \cref{eq:average-gradient-decomposition}. By Stein's Lemma (\cref{lem:hypercube-stein}) and \cref{eq:tensor-pca-overlap-noise},
\begin{align*}
    \zeta
    =\mathbb{E}_\pi[\nabla_\Omega H_0(x)]
    =\mathbb{E}_\pi[xH_0(x)]
    =N^{-\tfrac{k-1}{2}}\mathbb{E}_{x\sim\pi}\left[x\left\langle G, x^{\otimes k} \right\rangle\right]
    =\Lambda(G),
\end{align*}
where $\Lambda:(\mathbb{R}^N)^{\otimes k}\to\mathbb{R}^N$ is a linear operator. Since $G$ is a centered Gaussian tensor, $\zeta\sim\mathcal{N}(0,\Sigma)$ for some covariance matrix $\Sigma$.

We now prove that the law of $\zeta$ is invariant under $O(N,\mathbb Z)$. Fix $U\in O(N,\mathbb Z)\subseteq O(N)$. By rotational invariance of the standard Gaussian, $U^{\otimes k}G\overset{\mathrm{d}}{=} G$. Moreover, $U^\top x\sim\pi$ whenever $x\sim\pi$. Making the appropriate change of variables, we obtain
\begin{align*}
    \Lambda(U^{\otimes k}G)
    &=N^{-\tfrac{k-1}{2}}\mathbb{E}_{x\sim\pi}
      \left[x\left\langle U^{\otimes k}G, x^{\otimes k} \right\rangle\right]\\
    &=N^{-\tfrac{k-1}{2}}\mathbb{E}_{x\sim\pi}
      \left[x\left\langle G, (U^\top x)^{\otimes k} \right\rangle\right]\\
    &=N^{-\tfrac{k-1}{2}}U\mathbb{E}_{y\sim\pi}
      \left[y\left\langle G, y^{\otimes k} \right\rangle\right]
    =U\Lambda(G).
\end{align*}
Together with $U^{\otimes k}G\overset{\mathrm{d}}{=} G$, this implies that
\begin{align*}
    \zeta=\Lambda(G)
    \overset{\mathrm{d}}{=}\Lambda(U^{\otimes k}G)
    =U\Lambda(G)
    =U\zeta.
\end{align*}
Consequently, for every $U\in O(N,\mathbb Z)$,
\begin{align*}
    \Sigma
    =\mathbb{E}_G[\zeta\zeta^\top]
    =\mathbb{E}_G[(U\zeta)(U\zeta)^\top]
    =U\mathbb{E}_G[\zeta\zeta^\top]U^\top
    =U\Sigma U^\top.
\end{align*}
Thus, $\Sigma$ commutes with every element of $O(N,\mathbb Z)$, and \cref{lem:commutants-bn} implies that $\Sigma=\sigma_N^2I$ for some $\sigma_N^2\geqslant0$. Finally, to compute $\sigma_N^2$, we take the trace and use \cref{eq:kspin-covariance} to obtain the following.
\begin{align*}
    \sigma_N^2
    &=\frac{1}{N}\operatorname{Tr}(\Sigma)
    =\frac{1}{N}\mathbb{E}_G[ 
    \IfNoValueTF{^}
