\label{thm:persistent-strong-recovery-algorithmic-threshold}
Let $k\geqslant3$ be odd, let $\beta>0$, and assume $\lambda\geqslant C_{\beta,k}N^{\tfrac{k-2}{4}}$, where $C_{\beta,k}$ is a sufficiently large constant. Fix $\vartheta\in(0,1)$ and $\eta\in(0,\nicefrac{1}{2})$, and let $(X_t)_{t\geqslant0}$ denote the trajectory of the second phase of \cref{alg:averaged-annealed-glauber}, initialized at $\widetilde{X}_0\sim\pi$ with inverse temperatures $\beta_0$ and $\beta$ for the two respective phases, where $\beta_0\asymp_k\lambda^{-1}N^{-\nicefrac{k}{2}-\vartheta}$ and $T_{\mathrm{av}}\asymp_kN^{2k+4\vartheta}$. Set $T_{\mathrm{str}}\doteq\log N$. Then, for all sufficiently large $N$ and every deterministic $T$ satisfying $T_{\mathrm{str}}\leqslant T\leqslant\operatorname{poly}(N)$,
\begin{align*}
    \mathbb{P}\left[\inf_{t\in[T_{\mathrm{str}},T]}m(X_t)\geqslant1-N^{-\eta}\right]
    \geqslant1-\exp\left(-c_{\beta,k}N^{\min\{(1-\vartheta)/2,\,1-2\eta\}}\right).
\end{align*}

\label{thm:strong-recovery-after-critical-correlation}
Fix $\eta,s\in(0,\nicefrac{1}{2})$, define $\bar r_N\doteq N^{-s}$, and assume that $\lambda\bar r_N^{k-1}\geqslant C_{\beta,k}$. Define the stopping time
\begin{align*}
    \tau_{C\bar r_N}\doteq\inf\{t\geqslant0:m(X_t)\geqslant C\bar r_N\},
\end{align*}
where $C\geqslant 1$ is a constant, and set $T_{\mathrm{str}}\doteq1+2\eta\log N$. Then, the following holds for all sufficiently large $N$, every deterministic $T$ satisfying $T_{\mathrm{str}}\leqslant T\leqslant\operatorname{poly}(N)$, and any initial state $X_0$, possibly depending on $H$,
\begin{align*}
    \mathbb{P}\left[\inf_{t\in[T_{\mathrm{str}},T]}m(X_{\tau_{C\bar r_N}+t})\geqslant1-N^{-\eta}\right]
    \geqslant1-\exp(-c_kN)-2\exp\left(-cN\min\{\bar r_N^2,N^{-2\eta}\}\right).
\end{align*}

Write $q_N\doteq N^{-\eta}$ and $\varepsilon_N\doteq\tfrac{1}{32}\min\{\bar r_N,q_N\}$. Throughout the proof, we assume that $N$ is sufficiently large and $C_{\beta, k}$ is a sufficiently large constant. By the strong Markov property~\citep[Chapter~4]{ethier1986markov} applied at the stopping time $\tau_{C\bar r_N}$, it suffices to consider an initial state $X_0$ with $m(X_0)\geqslant C\bar r_N$, possibly depending on $H$.

Since $\nabla_\Omega m=x^{\star}/N$ and $\tanh$ is odd, we infer from \cref{eq:srw-generator,eq:glauber-generator-srw-decomposition} that
\begin{align}
\label{eq:strong-recovery-overlap-drift}
    \mathcal{L}_{H,\beta}m(x)
    &=-m(x)+\frac1N\sum_{i=1}^N\tanh\bigl(\betax^{\star}_i\partial_iH(x)\bigr)
      =1-m(x)-2b(x),\\
    b(x)&\doteq\frac{1}{2N}\sum_{i=1}^N\Bigl[1-\tanh\bigl(\betax^{\star}_i\partial_iH(x)\bigr)\Bigr].\nonumber
\end{align}
Let $M_t^m$ denote the Dynkin martingale associated with $m$. By \cref{lem:single-site-dynkin},
\begin{align}
\label{eq:strong-recovery-dynkin}
    M_t^m=m(X_t)-m(X_0)-\int_0^t\mathcal{L}_{H,\beta}m(X_s)\,ds.
\end{align}
Consider the events
\begin{align*}
    \mathcal{E}\doteq\left\{\max_{x\in\Omega_N} 
    \IfNoValueTF{^}
        {\IfBooleanTF{\nabla_\Omega H_0(x)}{\normdelim{#3}}{\normdelim*{#3}}}
        {\normdelim[^]{#3}} 
2\leqslant C_1N\right\},
    \qquad
    \mathcal M_j\doteq\left\{\sup_{j\leqslant t\leqslant j+1}\bigl|M_t^m-M_j^m\bigr|\leqslant\varepsilon_N\right\},
\end{align*}
and let $\mathcal M\doteq\bigcap_{j=0}^{\lceil T\rceil-1}\mathcal M_j$. By \cref{lem:kspin-sobolev-norm-concentration}, we can choose $C_1$ such that $\mathbb{P}[\mathcal{E}]\geqslant1-\exp(-c_kN)$. Moreover, since $ 
