\end{align*}
Observe that
\begin{align*}
    \bigl\{\tau=\tau^{\mathrm{bad}}<T_*^Y(e)\bigr\}^c
    =\{\tau<\tau^{\mathrm{bad}}\}\cup\{\tau=T_*^Y(e)\}.
\end{align*}
Moreover, since $\tau\leqslant T_\lambda$, we have $\mathcal M_{T_\lambda}\subseteq\mathcal M_\tau$. Hence, $\mathcal{E}_{\mathrm{good}}=\mathcal{I}\cap\mathcal{E}_{\mathrm{reg}}\cap\mathcal M_{T_\lambda}\cap\mathcal{E}_{\mathrm{fail}}^c$, and we infer from \cref{eq:critical-recovery-event-probabilities,eq:critical-recovery-failure-probability} and a union bound that
\begin{align*}
