\end{align*}
Henceforth, we work on $\mathcal{E}_{\mathrm{good}}$. Since $\mathcal M_{T_\lambda}\subseteq\mathcal M_\tau$, \cref{eq:critical-recovery-overlap-bounds,eq:critical-recovery-integral-inequality} hold. We first turn \cref{eq:critical-recovery-integral-inequality} into an explicit lower bound on the correlation. To this end, define the blow-up time
\begin{align*}
    t_\infty
    \doteq\frac{(a_0/2)^{-(k-2)}}{(k-2)\eta\lambda}
    =\frac{2^{k-2}}{(k-2)\eta\lambda a_0^{k-2}}.
\end{align*}
By our choice of $C_T$, we have $t_\infty=T_\lambda/2<T_\lambda$. Since $31a_0/32\geqslant a_0/2$, applying \cref{lem:power-law-gronwall} to $f(t)=m_t$ on $[0,\tau]$ with $a=a_0/2$ and $c=\eta\lambda$, we infer from \cref{eq:critical-recovery-integral-inequality} that
\begin{align}
\label{eq:critical-recovery-power-law}
    m_t
    \geqslant\Bigl[\Bigl(\frac{a_0}{2}\Bigr)^{-(k-2)}-(k-2)\eta\lambda t\Bigr]^{-\frac{1}{k-2}}
    \qquad\forall\,t\in[0,\tau\wedge t_\infty).
\end{align}

We now examine which of the stopping times attains the minimum in the definition of $\tau$. By \cref{eq:critical-recovery-overlap-bounds}, we have $m_\tau\geqslant31a_0/32>a_0/2$, and hence $\tau\ne\tau^{\downarrow}$. Therefore, one of the following two cases holds.

\textbf{Case 1: $\tau=T_*^Y(e)$.} In this case, we have $T_*^Y(e)=\tau\leqslant T_\lambda$, and we are done.

\textbf{Case 2: $\tau<T_*^Y(e)$.} By definition of $\mathcal{E}_{\mathrm{good}}$, we must have $\tau<\tau^{\mathrm{bad}}$, and hence $\tau=T_\lambda$. Moreover, since $T_*^Y(e)>0$, we have $a_0\leqslant m_0<Cr_N$. Define
\begin{align*}
    t_*\doteq\frac{(a_0/2)^{-(k-2)}-(2Cr_N)^{-(k-2)}}{(k-2)\eta\lambda}.
\end{align*}
Since $a_0/2<2Cr_N$, we have $0<t_*<t_\infty<T_\lambda=\tau$. Hence, \cref{eq:critical-recovery-power-law} holds at $t=t_*$, which implies that
\begin{align*}
    m_{t_*}
    \geqslant\Bigl[\Bigl(\frac{a_0}{2}\Bigr)^{-(k-2)}-(k-2)\eta\lambda t_*\Bigr]^{-\frac{1}{k-2}}
    =2Cr_N.
\end{align*}
Consequently, $T_*^Y(e)\leqslant t_*<\tau$, which contradicts $\tau<T_*^Y(e)$. Hence, this case cannot occur.

Combining the two cases, we have $T_*^Y(e)\leqslant T_\lambda$ on $\mathcal{E}_{\mathrm{good}}$, and after adjusting constants, we conclude that
\begin{align}
\label{eq:critical-recovery-fixed-initialization}
    \mathbb{P}\bigl[T_*^Y(e)>T_\lambda\bigr]\leqslant\exp\bigl(-cN\lambda^2\sigma_N^2\bigr).
\end{align}

Finally, we invert the gauge transformation and take a union bound over the initialization. Since $\operatorname{sgn}(u_H)=x^{\star}\odot\phi$ under the planted law, and the gauge transformation $x\mapstox^{\star}\odot\phi\odot x$ is an isometric involution of $\Omega_N$, it maps $\mathcal{B}_H(\operatorname{sgn}(u_H),r)$ isometrically onto $\mathcal{B}_H(\mathbf{1},r)$ for every $r>0$. Moreover, $m(X_t(x^{\star}\odot\phi\odot e))=m_\phi(Y_t(e))$, and hence $T_*(x^{\star}\odot\phi\odot e)=T_*^Y(e)$ for every $e\in\Omega_N$. Consequently, we infer from \cref{eq:critical-recovery-fixed-initialization} that the following holds for every $e\in\mathcal{B}_H(\mathbf{1},\lambda^2\sigma_N^2N^{-\vartheta})$:
\begin{align*}
    \mathbb{P}\bigl[T_*(x^{\star}\odot\phi\odot e)>T_\lambda\bigr]\leqslant\exp\bigl(-cN\lambda^2\sigma_N^2\bigr).
\end{align*}
Since $\abs{\mathcal{B}_H(\mathbf{1},r)}\leqslant(3/r)^{rN}$ for $r\in(0,\nicefrac{1}{2}]$ and $\lambda^2\sigma_N^2\gtrsim N^{-\nicefrac{1}{2}}$, we have $\log\abs{\mathcal{B}_H(\mathbf{1},\lambda^2\sigma_N^2N^{-\vartheta})}=o(N\lambda^2\sigma_N^2)$. Hence, a union bound over $e\in\mathcal{B}_H(\mathbf{1},\lambda^2\sigma_N^2N^{-\vartheta})$ yields
\begin{align*}
    \mathbb{P}\Bigl[T_*(e)\leqslant T_\lambda\ \ \forall\,e\in\mathcal{B}_H\bigl(\operatorname{sgn}(u_H),\lambda^2\sigma_N^2N^{-\vartheta}\bigr)\Bigr]
    \geqslant1-\exp\bigl(-cN\lambda^2\sigma_N^2\bigr).
\end{align*}
The proof is concluded by noting that $T_\lambda=C_T/(\lambda a_0^{k-2})\lesssim N^{-(k-1)(\gamma-\frac{k-2}{4})}$, with implicit constants depending only on $\beta$, $k$ and $C$.

Throughout the proof, we assume that $N$ is sufficiently large. Since $\beta_0^{-2}\lambda^{-2}N^{k+2\vartheta}\asymp_kN^{2k+4\vartheta}$, our choices of $\beta_0$ and $T_{\mathrm{av}}$ satisfy the assumptions of \cref{thm:tpca-averaged-differential-recovery}. By construction, $(X_t)_{t\geqslant0}$ is Glauber dynamics for $H$ at inverse temperature $\beta$, started from $X_0=\operatorname{sgn}(\bar{X}_{T_{\mathrm{av}}})$. If $\lambda\geqslant C_{\beta,k}N^{\tfrac{k-2}{4}+\tfrac{1}{4k}}$, the claim follows from \cref{cor:averaged-glauber-persistent-strong-recovery}.

Henceforth, we assume that $\lambda=C_{\beta,k}N^\gamma$ with $\tfrac{k-2}{4}\leqslant\gamma<\tfrac{k-2}{4}+\tfrac{1}{4k}$, and let $r_N\doteq\lambda^{-\tfrac{1}{k-1}}$, as in \cref{subsec:critical-recovery-warm-start}. We first show that the second phase attains critical correlation in constant time. We infer from \cref{thm:tpca-averaged-differential-recovery} that the following holds with probability at least $1-\exp(-c_kN^{(1-\vartheta)/2})$:
\begin{align*}
    X_0=\operatorname{sgn}(\bar{X}_{T_{\mathrm{av}}})
    \in\mathcal{B}_H\bigl(\operatorname{sgn}(u_H),\lambda^2\sigma_N^2N^{-\vartheta/2}\bigr).
\end{align*}
Since \cref{thm:critical-recovery-warm-start} holds simultaneously for all initializations in this Hamming ball, we may apply it with $\vartheta/2$ in place of $\vartheta$, and we obtain the following with probability at least $1-\exp(-c_kN^{(1-\vartheta)/2})-\exp(-cN\lambda^2\sigma_N^2)$ for some sufficiently large constant $C$:
\begin{align}
\label{eq:algorithmic-threshold-critical-time}
    T_*(X_0)=\inf\bigl\{t\geqslant0:m(X_t)\geqslant Cr_N\bigr\}\leqslant C_1N^{-(k-1)\left(\gamma-\tfrac{k-2}{4}\right)}.
\end{align}
Let $\bar r_N\doteq Cr_N$. Since $\lambda r_N^{k-1}=1$, we have $\lambda\bar r_N^{k-1}=C^{k-1}\geqslant C_{\beta,k}$. Hence, applying \cref{thm:strong-recovery-after-critical-correlation} on the event in \cref{eq:algorithmic-threshold-critical-time} with $\tau_{\bar r_N}=T_*(X_0)$, and using $T_{\mathrm{str}}\geqslant T_*(X_0)+1+2\eta\log N$ for sufficiently large $N$, we obtain the following via a union bound:
\begin{align*}
    \mathbb{P}\left[\inf_{t\in[T_{\mathrm{str}},T]}m(X_t)<1-N^{-\eta}\right]
    \leqslant\exp\bigl(-c_kN^{(1-\vartheta)/2}\bigr)+\exp\bigl(-cN\lambda^2\sigma_N^2\bigr)+3\exp\bigl(-cN\min\{\bar r_N^2,N^{-2\eta}\}\bigr).
\end{align*}
Finally, since $\gamma<\tfrac{k-2}{4}+\tfrac{1}{4k}$, we have $N\bar r_N^2\gtrsim N^{\tfrac{k+1}{2k}}$. As $N\lambda^2\sigma_N^2\gtrsim\sqrt N$ and $\tfrac{k+1}{2k}>\nicefrac{1}{2}>\tfrac{1-\vartheta}{2}$, the claim follows after adjusting constants appropriately.

\label{thm:persistent-strong-recovery-every-order}
Let $k\geqslant3$, let $\beta>0$, and assume $\lambda\geqslant C_{\beta,k}N^{\tfrac{k-2}{4}}$, where $C_{\beta,k}$ is a sufficiently large constant. Fix $\vartheta\in(0,1)$ and $\eta\in(0,\nicefrac{1}{2})$, and let $(X_t)_{t\geqslant0}$ denote the trajectory of the second phase of \cref{alg:annealed-glauber-ergodic-second-moments}, initialized at $\widetilde{X}_0\sim\pi$ with inverse temperatures $\beta_0$ and $\beta$ for the two respective phases, where $\beta_0\asymp_k\lambda^{-1}N^{-\tfrac{k+1}{2}-\vartheta}$ and $T_{\mathrm{av}}\asymp_kN^{2k+2+4\vartheta}$. Set $T_{\mathrm{str}}\doteq\log N$. Then, for all sufficiently large $N$ and every deterministic $T$ satisfying $T_{\mathrm{str}}\leqslant T\leqslant\operatorname{poly}(N)$,
\begin{align*}
    \mathbb{P}\left[\inf_{t\in[T_{\mathrm{str}},T]}\abs{m(X_t)}\geqslant1-N^{-\eta}\right]
    \geqslant1-\exp\left(-c_{\beta,k}N^{\min\{(1-\vartheta)/2,\,1-2\eta\}}\right).
\end{align*}
Moreover, if $k$ is odd, the same bound holds with $m(X_t)$ in place of $\abs{m(X_t)}$.

