\sqrt{C_1N}
    \leqslant\frac{k}{2}\lambda\left(\frac{\rho}{2}\right)^{k-1}
    \qquad\forall\,x\in\Omega_N,\ i\in[N].
\end{align}
Since $H=N\lambda\widetilde m^k+H_0$ and $\rho\geqslant4/N$, we infer from \cref{eq:weak-to-strong-signal-field,eq:weak-to-strong-disorder-bound} that the following holds for every $x\in\Omega_N$ with $\widetilde m(x)\geqslant\rho$ and every $i\in[N]$:
\begin{align}
\label{eq:weak-to-strong-derivative-bound}
    \widetilde x^\star_i\partial_iH(x)
    \geqslant k\lambda\left(\frac{\widetilde m(x)}{2}\right)^{k-1}-\abs{\partial_iH_0(x)}
    \geqslant k\lambda\left(\frac{\rho}{2}\right)^{k-1}-\sqrt{C_1N}
    \geqslant\frac{k}{2}\lambda\left(\frac{\rho}{2}\right)^{k-1}.
\end{align}
For $x\in\Omega_N$ and $i\in[N]$, let $q_i(x)$ denote the probability that an update of coordinate $i$ at state $x$ sets its spin to $-\widetilde x^\star_i$. Since the site update kernel of Glauber dynamics is $q(z\mid i,t,x)=\nicefrac{1}{2}(1+z\tanh(\beta\partial_iH(x)))$ by \cref{subsec:cts-glauber}, we infer from \cref{eq:weak-to-strong-derivative-bound} that the following holds for every $x\in\Omega_N$ with $\widetilde m(x)\geqslant\rho$ and every $i\in[N]$:
\begin{align}
\label{eq:weak-to-strong-bad-update}
    q_i(x)
    =\frac{1}{1+\exp\bigl(2\beta\widetilde x^\star_i\partial_iH(x)\bigr)}
    \leqslant\exp\left(-k\beta\lambda\left(\frac{\rho}{2}\right)^{k-1}\right)
    \doteq p.
\end{align}

We now realize the trajectory of Glauber dynamics using auxiliary uniform random variables. Let $(T_n)_{n\geqslant1}$ denote the arrival times of a rate $N$ Poisson process, with marks $(I_n)_{n\geqslant1}\overset{\mathrm{i.i.d.}}{\sim}\operatorname{Uniform}([N])$ and $(\omega_n)_{n\geqslant1}\overset{\mathrm{i.i.d.}}{\sim}\operatorname{Uniform}([0,1])$. The arrival times and marks are mutually independent, and independent of $H$ and $X_0$. At time $T_n$, the process sets coordinate $I_n=i$ of $X_{T_n}$ to $-\widetilde x^\star_i$ if $\omega_n\leqslant q_i(X_{T_n^-})$, and to $\widetilde x^\star_i$ otherwise. By \cref{subsec:cts-glauber}, the resulting trajectory is Glauber dynamics for $H$ at inverse temperature $\beta$, initialized at $X_0$.

We call the arrival $T_n$ bad if $\omega_n\leqslant p$, and let $B_T$ denote the number of bad arrivals in $[0,T]$. Since $p$ is deterministic, Poisson thinning implies $B_T\sim\operatorname{Poisson}(NTp)$, and hence
\begin{align*}
    \mathbb{P}[B_T>0]
    =1-e^{-NTp}
    \leqslant NTp.
\end{align*}
Moreover, let $U_t$ denote the number of coordinates that are not updated during $[0,t]$. Precisely, define
\begin{align*}
    N_i(t)\doteq\#\{n:T_n\leqslant t,\ I_n=i\},
    \qquad
    U_t\doteq\sum_{i=1}^N\mathbf{1}\!\left\{N_i(t)=0\right\}.
\end{align*}
By Poisson thinning, $(N_i(t))_{t\geqslant0}$ are independent rate one Poisson processes for $i\in[N]$, and hence $U_t\sim\operatorname{Bin}(N,e^{-t})$. In particular, since $T_{\mathrm{str}}=\log N$, we have $U_{T_{\mathrm{str}}}\sim\operatorname{Bin}(N,\nicefrac{1}{N})$, and a Chernoff bound implies
\begin{align*}
    \mathbb{P}\left[U_{T_{\mathrm{str}}}>\frac12N^{1-\eta}\right]
    \leqslant\exp(-cN^{1-\eta}).
\end{align*}
Henceforth, we work on the event $\mathcal{E}\cap\{B_T=0\}\cap\{U_{T_{\mathrm{str}}}\leqslant\tfrac12N^{1-\eta}\}$.

We now show by induction that each update during $[0,T]$ sets the updated spin to its value in $\widetilde x^\star$. Consider any $n$ with $T_n\leqslant T$, and suppose that the claim holds for all earlier updates. Since such updates can only increase $\widetilde m$, we have
\begin{align*}
    \widetilde m(X_{T_n^-})
    \geqslant\widetilde m(X_0)
    \geqslant\rho.
\end{align*}
Hence, by \cref{eq:weak-to-strong-bad-update} and since we work on $\{B_T=0\}$, we obtain $q_{I_n}(X_{T_n^-})\leqslant p<\omega_n$. Therefore, coordinate $I_n$ is set to $\widetilde x^\star_{I_n}$, which completes the induction.

Consequently, for every $t\in[0,T]$, each coordinate that is updated during $[0,t]$ agrees with $\widetilde x^\star$ at time $t$, and hence $d_H(X_t,\widetilde x^\star)\leqslant U_t$. Since $U_t$ is nonincreasing in $t$, we conclude that
\begin{align*}
    \abs{m(X_t)}
    \geqslant\widetilde m(X_t)
    =1-\frac{2}{N}d_H(X_t,\widetilde x^\star)
    \geqslant1-\frac{2}{N}U_{T_{\mathrm{str}}}
    \geqslant1-N^{-\eta}
    \qquad\forall\,t\in[T_{\mathrm{str}},T].
\end{align*}
The proof is concluded via a union bound over $\mathcal{E}^c$, $\{B_T>0\}$ and $\{U_{T_{\mathrm{str}}}>\tfrac12N^{1-\eta}\}$.

Throughout the proof, we assume that $N$ is sufficiently large. Our choices of $\beta_0$ and $T_{\mathrm{av}}$ satisfy the assumptions of \cref{thm:recovery-ergodic-second-moments}, since $\beta_0^{-2}\lambda^{-2}N^{k+1+2\vartheta}\asymp_kN^{2k+2+4\vartheta}$. By construction, $(X_t)_{t\geqslant0}$ is Glauber dynamics for $H$ at inverse temperature $\beta$, started from $X_0=\operatorname{sgn}(v)$.

We first analyze the case when $k$ is odd, wherein we prove the claim with $m(X_t)$ in place of $\abs{m(X_t)}$. Without loss of generality, let $\lambda=C_{\beta,k}N^\gamma$ with $\gamma\geqslant\tfrac{k-2}{4}$. We infer from \cref{thm:recovery-ergodic-second-moments} that the following holds with probability at least $1-\exp(-c_kN^{(1-\vartheta)/2})$:
\begin{align}
\label{eq:every-order-warm-start}
    X_0=\operatorname{sgn}(v)
    \in\mathcal{B}_H\bigl(\operatorname{sgn}(u_H),\min\{N^{-\vartheta},\lambda^2\sigma_N^2N^{-\vartheta/2}\}\bigr).
\end{align}

We first consider the regime $\gamma\geqslant\tfrac{k-2}{4}+\tfrac{1}{4k}$. In this regime, we show that the correlation of $X_0$ is already large enough to apply \cref{thm:strong-recovery-after-critical-correlation}. Define $a\doteq\tfrac{k-1}{4k}$, and note that $\gamma-\tfrac{k-1}{4}\geqslant-a$, so that $\lambda\sigma_N\gtrsim_kC_{\beta,k}N^{-a}$. Combining \cref{eq:every-order-warm-start} with \cref{cor:avg-discrete-grad-correlation}, and using $\sigma_N\asymp_kN^{-\tfrac{k-1}{4}}$ and $\min\{N^{-\vartheta},\lambda^2\sigma_N^2N^{-\vartheta/2}\}\leqslant N^{-\vartheta/2}\min\{1,\lambda\sigma_N\}$, we obtain the following with probability at least $1-\exp(-c_kN^{(1-\vartheta)/2})$, after choosing $C_{\beta,k}$ sufficiently large:
\begin{align}
\label{eq:every-order-initial-correlation}
    m(X_0)
    &\geqslant m(\operatorname{sgn}(u_H))-\frac{2}{N}d_H\bigl(X_0,\operatorname{sgn}(u_H)\bigr)\nonumber\\
    &\geqslant\bigl(c_k-2N^{-\vartheta/2}\bigr)\min\{1,\lambda\sigma_N\}
    \geqslant\frac{c_k}{2}\min\{1,\lambda\sigma_N\}
    \geqslant N^{-a}.
\end{align}
Let $\bar r_N\doteq N^{-a}$. Since $\gamma\geqslant(k-1)a$, we have $\lambda\bar r_N^{k-1}\geqslant C_{\beta,k}$. Hence, applying \cref{thm:strong-recovery-after-critical-correlation} on the event in \cref{eq:every-order-initial-correlation} with $C=1$ and $\tau_{\bar r_N}=0$, and using $T_{\mathrm{str}}\geqslant1+2\eta\log N$ for sufficiently large $N$, we obtain the following via a union bound:
\begin{align*}
    \mathbb{P}\left[\inf_{t\in[T_{\mathrm{str}},T]}m(X_t)<1-N^{-\eta}\right]
    \leqslant\exp\bigl(-c_kN^{(1-\vartheta)/2}\bigr)+3\exp\bigl(-cN\min\{\bar r_N^2,N^{-2\eta}\}\bigr).
\end{align*}
Finally, since $1-2a=\tfrac{k+1}{2k}>\nicefrac{1}{2}>\tfrac{1-\vartheta}{2}$, the claim follows after adjusting constants appropriately.

We now consider the regime $\tfrac{k-2}{4}\leqslant\gamma<\tfrac{k-2}{4}+\tfrac{1}{4k}$, and let $r_N\doteq\lambda^{-\tfrac{1}{k-1}}$, as in \cref{subsec:critical-recovery-warm-start}. In this regime, our argument closely mirrors the proof of \cref{thm:persistent-strong-recovery-algorithmic-threshold}. We first show that the second phase attains critical correlation in constant time. By \cref{eq:every-order-warm-start}, we have $X_0\in\mathcal{B}_H(\operatorname{sgn}(u_H),\lambda^2\sigma_N^2N^{-\vartheta/2})$. Since \cref{thm:critical-recovery-warm-start} holds simultaneously for all initializations in this Hamming ball, we may apply it with $\vartheta/2$ in place of $\vartheta$, and we obtain the following with probability at least $1-\exp(-c_kN^{(1-\vartheta)/2})-\exp(-cN\lambda^2\sigma_N^2)$ for some sufficiently large constant $C$:
\begin{align}
\label{eq:every-order-critical-time}
    T_*(X_0)=\inf\bigl\{t\geqslant0:m(X_t)\geqslant Cr_N\bigr\}\leqslant C_1N^{-(k-1)\left(\gamma-\tfrac{k-2}{4}\right)}.
\end{align}
Let $\bar r_N\doteq Cr_N$. Since $\lambda r_N^{k-1}=1$, we have $\lambda\bar r_N^{k-1}=C^{k-1}\geqslant C_{\beta,k}$. Hence, applying \cref{thm:strong-recovery-after-critical-correlation} on the event in \cref{eq:every-order-critical-time} with $\tau_{\bar r_N}=T_*(X_0)$, and using $T_{\mathrm{str}}\geqslant T_*(X_0)+1+2\eta\log N$ for sufficiently large $N$, we obtain the following via a union bound:
\begin{align*}
    \mathbb{P}\left[\inf_{t\in[T_{\mathrm{str}},T]}m(X_t)<1-N^{-\eta}\right]
    \leqslant\exp\bigl(-c_kN^{(1-\vartheta)/2}\bigr)+\exp\bigl(-cN\lambda^2\sigma_N^2\bigr)+3\exp\bigl(-cN\min\{\bar r_N^2,N^{-2\eta}\}\bigr).
\end{align*}
Finally, since $\gamma<\tfrac{k-2}{4}+\tfrac{1}{4k}$, we have $N\bar r_N^2\gtrsim N^{\tfrac{k+1}{2k}}$. As $N\lambda^2\sigma_N^2\gtrsim\sqrt N$ and $\tfrac{k+1}{2k}>\nicefrac{1}{2}>\tfrac{1-\vartheta}{2}$, the claim follows after adjusting constants appropriately.

Finally, we analyze the case when $k$ is even. Since $C_{\beta,k}$ is sufficiently large, we infer from \cref{thm:recovery-ergodic-second-moments} that the following holds with probability at least $1-\exp(-c_kN)$:
\begin{align}
\label{eq:every-order-weak-recovery}
    \abs{m(X_0)}=\bigl|m(\operatorname{sgn}(v))\bigr|\geqslant\frac12.
\end{align}
Hence, applying \cref{thm:strong-recovery-after-weak-recovery} on the event in \cref{eq:every-order-weak-recovery} with $\rho=\nicefrac{1}{2}$ and $C_{\beta,k}$ sufficiently large, we obtain the following via a union bound:
\begin{align*}
    \mathbb{P}\left[\inf_{t\in[T_{\mathrm{str}},T]}\abs{m(X_t)}<1-N^{-\eta}\right]
    \leqslant2\exp(-c_kN)+\exp(-cN^{1-\eta})+NT\exp\bigl(-k\beta\lambda4^{1-k}\bigr).
\end{align*}
Moreover, since $k\geqslant4$, we have $\lambda\geqslant C_{\beta,k}\sqrt N$, so $NT\exp(-k\beta\lambda4^{1-k})\leqslant\exp(-c_{\beta,k}\sqrt N)$ for $T\leqslant\operatorname{poly}(N)$. Finally, since $\nicefrac{1}{2}>\tfrac{1-\vartheta}{2}$ and ${1-\eta>1-2\eta}$, the claim follows after adjusting constants appropriately.

Since $G$ is the symmetrization of a standard Gaussian $k$-tensor $\widetilde G$, $\left\langle G, x^{\otimes k} \right\rangle=\left\langle \widetilde G, x^{\otimes k} \right\rangle$. Thus, \cref{eq:tensor-pca-overlap-noise} gives
\begin{align*}
    H_0(x)=N^{-\tfrac{k-1}{2}}\sum_{i_1,\ldots,i_k\in[N]}\widetilde G_{i_1,\ldots,i_k}\cdot\prod_{r=1}^k x_{i_r}.
\end{align*}

Fix $\ell\in\{1,\ldots,k\}$. By repeated applications of \cref{eq:partial-fourier-character} we obtain the following for any $S\subseteq[N]$,
\begin{align}
\label{eq:kspin-character-derivatives}
    \partial_{i_1}\cdots\partial_{i_\ell}\chi_S(x)
    =\begin{cases}
        \chi_{S\setminus\{i_1,\ldots,i_\ell\}}(x), & \text{if } i_1,\ldots,i_\ell\in S\text{ are distinct},\\
        0, & \text{otherwise}.
    \end{cases}
\end{align}

For any multi-index $I=(i_1,\ldots,i_k)\in[N]^k$, define
\begin{align*}
    A(I)=\left\{j\in[N]:\#\{r:i_r=j\}\text{ is odd}\right\}.
\end{align*}
Since $x_j^2=1$ for every $j\in[N]$, the factors with even multiplicity cancel, and hence
\begin{align*}
    \prod_{r=1}^k x_{i_r}=\prod_{j\in A(I)}x_j=\chi_{A(I)}(x).
\end{align*}
Using the above identity to write $H_0$ as a sum of Fourier characters:
\begin{align*}
    H_0(x)=N^{-\tfrac{k-1}{2}}\sum_{I\in[N]^k}\widetilde G_I \cdot \chi_{A(I)}(x).
\end{align*}
Applying \cref{eq:kspin-character-derivatives} term by term, we obtain the following for distinct $i_1,\ldots,i_\ell\in[N]$,
\begin{align}
    \partial_{i_1}\cdots\partial_{i_\ell}H_0(x)
    &=N^{-\tfrac{k-1}{2}}\sum_{I\in[N]^k}\widetilde G_I\cdot
    \partial_{i_1}\cdots\partial_{i_\ell}\chi_{A(I)}(x)\nonumber\\
    &=N^{-\tfrac{k-1}{2}}\sum_{I\in[N]^k}\widetilde G_I\cdot
    \chi_{A(I)\setminus\{i_1,\ldots,i_\ell\}}(x)\cdot
    \mathbf{1}\!\left\{\{i_1,\ldots,i_\ell\}\subseteq A(I)\right\}.
\label{eq:kspin-partial-derivatives}
\end{align}

Consider any $a^{(1)},\ldots,a^{(\ell)}\in\mathbb{S}^{N-1}$ and let $Z=\nabla_\Omega^\ell H_0(x)[a^{(1)},\ldots,a^{(\ell)}]$. From the above identity, we obtain
\begin{align*}
    Z
    &=\sum_{j_1,\ldots,j_\ell\in[N]}
    \partial_{j_1}\cdots\partial_{j_\ell}H_0(x)\cdot\prod_{r=1}^{\ell}a_{j_r}^{(r)}
    =N^{-\tfrac{k-1}{2}}\sum_{I\in[N]^k}\widetilde G_I\cdot C_I,
\end{align*}
where
\begin{align*}
    C_I
    =\sum_{\substack{j_1,\ldots,j_\ell\in A(I)\\ j_1,\ldots,j_\ell\ \mathrm{distinct}}}
    \chi_{A(I)\setminus\{j_1,\ldots,j_\ell\}}(x)\cdot\prod_{r=1}^{\ell}a_{j_r}^{(r)}.
\end{align*}
Since $|\chi_A(x)|=1$ and $|A(I)|\leqslant k$, we obtain the following by Cauchy--Schwarz:
\begin{align*}
    |C_I|^2
    &\leqslant\#\{(j_1,\ldots,j_\ell):j_1,\ldots,j_\ell\in A(I)\text{ distinct}\}
    \sum_{\substack{j_1,\ldots,j_\ell\in A(I)\\ j_1,\ldots,j_\ell\ \mathrm{distinct}}}
    \prod_{r=1}^{\ell}(a_{j_r}^{(r)})^2\\
    &\leqslant k^\ell
    \sum_{\substack{j_1,\ldots,j_\ell\in A(I)\\ j_1,\ldots,j_\ell\ \mathrm{distinct}}}
    \prod_{r=1}^{\ell}(a_{j_r}^{(r)})^2.
\end{align*}

Since $\widetilde G_I\overset{\mathrm{i.i.d.}}{\sim}\mathcal{N}(0,1)$ for $I\in[N]^k$,
\begin{align*}
    \operatorname{Var}(Z)
    &=N^{-(k-1)}\sum_{I\in[N]^k}|C_I|^2\\
    &\leqslant k^\ell N^{-(k-1)}
    \sum_{\substack{j_1,\ldots,j_\ell\in[N]\\ j_1,\ldots,j_\ell\ \mathrm{distinct}}}
    \#\{I\in[N]^k:j_1,\ldots,j_\ell\in A(I)\}
    \prod_{r=1}^{\ell}(a_{j_r}^{(r)})^2\\
    &\leqslant k^\ell N^{-(k-1)}\cdot N^{k-\ell}\cdot k(k-1)\cdots(k-\ell+1)
    \sum_{\substack{j_1,\ldots,j_\ell\in[N]\\ j_1,\ldots,j_\ell\ \mathrm{distinct}}}
    \prod_{r=1}^{\ell}(a_{j_r}^{(r)})^2\\
    &\leqslant k^{2\ell}N^{1-\ell}.
\end{align*}
Therefore, by Gaussian concentration, for any fixed $x\in\Omega_N$ and $a^{(1)},\ldots,a^{(\ell)}\in\mathbb{S}^{N-1}$,
\begin{align*}
