For the second bound, let $g(t)=t^k$. For any $A\subseteq[N]$, define $m_{-A}(x)=\nicefrac{1}{N}\sum_{i\notin A}x^{\star}_i x_i$, and write $m_{-i}=m_{-\{i\}}$. Since $m(x)=m_{-i}(x)+\tfrac{x^{\star}_i x_i}{N}$, we have
\begin{align*}
    \partial_i(m^k)(x)
    &=\frac{1}{2}\left[g\left(m_{-i}(x)+\frac{x^{\star}_i}{N}\right)
    -g\left(m_{-i}(x)-\frac{x^{\star}_i}{N}\right)\right]\\
    &=\frac{x^{\star}_i}{2N}\int_{-1}^1g'\left(m_{-i}(x)+t\frac{x^{\star}_i}{N}\right)\,dt.
\end{align*}

More generally, fix $\ell\geqslant1$ and distinct $i_1,\ldots,i_\ell\in[N]$, and let $A=\{i_1,\ldots,i_\ell\}$. Applying the fundamental theorem of calculus successively in the remaining coordinates, we obtain
\begin{align*}
    \partial_{i_1}\cdots\partial_{i_\ell}(m^k)(x)
    =\frac{\prod_{r=1}^{\ell}x^{\star}_{i_r}}{(2N)^\ell}
    \int_{[-1,1]^\ell}
    g^{(\ell)}\left(m_{-A}(x)+\frac{1}{N}\sum_{r=1}^{\ell}t_rx^{\star}_{i_r}\right)
    \,dt_1\cdots dt_\ell.
\end{align*}
For any $t_1,\ldots,t_\ell\in[-1,1]$, the argument of $g^{(\ell)}$ lies in $[-1,1]$. Hence,
\begin{align*}
    |\partial_{i_1}\cdots\partial_{i_\ell}(m^k)(x)|
    \leqslant\frac{1}{N^\ell}\max_{t\in[-1,1]}|g^{(\ell)}(t)|
    \leqslant C_{k,\ell}N^{-\ell}.
\end{align*}
When two indices coincide, the derivative vanishes because the discrete partial derivatives commute and $\partial_i^2(m^k)=0$, so the same bound holds.

Consider any $a^{(1)},\ldots,a^{(\ell)}\in\mathbb{S}^{N-1}$. By the triangle inequality and Cauchy--Schwarz, we obtain
\begin{align*}
    \left|\nabla_\Omega^\ell(m^k)(x)[a^{(1)},\ldots,a^{(\ell)}]\right|
    &\leqslant\sum_{i_1,\ldots,i_\ell\in[N]}
    |\partial_{i_1}\cdots\partial_{i_\ell}(m^k)(x)|\cdot
